/*---------------------------------------------------------------------------------------------
 *  poll tool - Poll a command with exponential backoff until a condition is met.
 *
 *  Essential for waiting on async external tasks:
 *    - CI pipeline completion
 *    - Container/VM readiness
 *    - Background job status
 *    - File system events (file appears, content matches)
 *
 *  Uses exponential backoff: delay doubles each attempt (1s → 2s → 4s → ... → max_delay)
 *  This prevents hammering the service while providing responsive detection.
 *--------------------------------------------------------------------------------------------*/

import { ITerminalService } from 'vs/workbench/contrib/terminal/browser/terminal';
import { IAgentConfig, IToolResult } from 'vs/workbench/services/agent/common/agentModels';
import { AgentTool } from '../agentTools';

/** Terminal create/dispose overhead per attempt, which the loop itself does not measure. */
const POLL_ATTEMPT_OVERHEAD_MS = 1000;

/**
 * Head-room kept between the poll's own deadline and the harness timeout that
 * races it. The harness clock starts slightly before `execute()` does, so the
 * poll has to give up a little early in order to be the one that reports the
 * outcome — otherwise the race rejects and every attempt already made is lost.
 */
const POLL_DEADLINE_MARGIN_MIN_MS = 250;
const POLL_DEADLINE_MARGIN_RATIO = 0.05;
const POLL_DEADLINE_MARGIN_MAX_MS = 30000;

/**
 * How much of the call budget the poll leaves to the harness. Never more than
 * half the budget, so a small budget still gets to run at least one attempt.
 */
export function pollDeadlineMarginMs(budgetMs: number): number {
	return Math.min(
		Math.max(POLL_DEADLINE_MARGIN_MIN_MS, budgetMs * POLL_DEADLINE_MARGIN_RATIO),
		POLL_DEADLINE_MARGIN_MAX_MS,
		budgetMs / 2,
	);
}

/**
 * Worst-case wall clock (ms) one poll call with these arguments can occupy its caller.
 *
 * Mirrors `execute()` exactly: every attempt may burn its full `command_timeout`,
 * and every attempt but the last may sleep its backoff delay. Keeping this in sync
 * with the loop is what stops the harness timeout from cutting the last attempt off
 * mid-flight.
 */
export function pollBudgetMs(args: Record<string, unknown>): number {
	const maxAttempts = Math.max(1, (args.max_attempts as number) || 30);
	const initialDelay = (args.initial_delay as number) || 2;
	const maxDelay = (args.max_delay as number) || 60;
	const commandTimeout = (args.command_timeout as number) || 30000;

	let total = maxAttempts * POLL_ATTEMPT_OVERHEAD_MS;
	for (let i = 0; i < maxAttempts; i++) {
		total += commandTimeout;
		if (i < maxAttempts - 1) {
			total += Math.min(initialDelay * Math.pow(2, i), maxDelay) * 1000;
		}
	}
	return total;
}

export class PollTool extends AgentTool {
	readonly name = 'poll';
	readonly description =
		`Poll a shell command at intervals with exponential backoff until a success condition is met. ` +
		`Use for waiting on async external tasks: CI pipelines, containers, background jobs, file readiness. ` +
		`The check command should exit 0 for success, or match success_pattern for text-based success. ` +
		`Delay grows exponentially (initial_delay → max_delay), never exceeding max_delay. ` +
		`Example: poll(command="curl -s http://svc/status", success_pattern="READY", max_attempts=10)`;
	readonly parameters = {
		type: 'object',
		properties: {
			command: {
				type: 'string',
				description:
					'Shell command to run for each poll attempt. ' +
					'Exit code 0 = success (unless success_pattern is set). ' +
					'Output is captured and checked against success_pattern if provided.',
			},
			success_pattern: {
				type: 'string',
				description:
					'Optional regex pattern. If set, the command is considered successful ' +
					'when its stdout matches this pattern (regardless of exit code). ' +
					'If not set, exit code 0 = success.',
			},
			max_attempts: {
				type: 'number',
				description: 'Maximum number of poll attempts before giving up. Default: 30.',
			},
			initial_delay: {
				type: 'number',
				description: 'Delay in seconds before the first retry. Default: 2.',
			},
			max_delay: {
				type: 'number',
				description: 'Maximum delay in seconds between attempts. Default: 60.',
			},
			cwd: {
				type: 'string',
				description: 'Working directory for the command. Defaults to workspace root.',
			},
			command_timeout: {
				type: 'number',
				description: 'Per-attempt command timeout in milliseconds. Default: 30000 (30s).',
			},
		},
		required: ['command'],
	};

	constructor(
		private readonly _terminalService: ITerminalService,
		private readonly _defaultCwd: string,
	) {
		super();
	}

	/**
	 * A poll is a deliberate wait: the generic step timeout (60s in the shipped
	 * config) is shorter than any real CI wait, so being killed by it is a
	 * guaranteed failure rather than a safety net. Declare the loop's own
	 * worst case instead — never shorter than the step timeout, never longer than
	 * the agent's configured task budget.
	 */
	override timeoutFor(args: Record<string, unknown>, config: IAgentConfig): number {
		const outerBound = Math.max(config.stepTimeout, config.taskTimeout);
		return Math.min(Math.max(pollBudgetMs(args), config.stepTimeout), outerBound);
	}

	async execute(args: Record<string, unknown>, signal?: AbortSignal): Promise<IToolResult> {
		const toolCallId = args._toolCallId as string || '';
		const command = args.command as string;
		const successPattern = args.success_pattern as string | undefined;
		const maxAttempts = (args.max_attempts as number) || 30;
		const initialDelay = (args.initial_delay as number) || 2;
		const maxDelay = (args.max_delay as number) || 60;
		const cwd = (args.cwd as string) || this._defaultCwd;
		const commandTimeout = (args.command_timeout as number) || 30000;

		// The harness races this call against the same budget `timeoutFor()`
		// declared. When the requested poll budget is larger than the agent's task
		// budget the harness clamps it, and losing that race throws away every
		// attempt already made (the "Tool execution timed out after 600000ms"
		// signature). Keep our own deadline just inside it so the poll reports
		// what it saw instead of being killed silently.
		const budgetMs = (args._timeoutMs as number) || 0;
		const deadline = budgetMs > 0
			? Date.now() + Math.max(0, budgetMs - pollDeadlineMarginMs(budgetMs))
			: Number.POSITIVE_INFINITY;

		if (maxAttempts < 1) {
			return this.failure(toolCallId, 'max_attempts must be >= 1');
		}

		// Check if already aborted
		if (signal?.aborted) {
			return this.failure(toolCallId, 'Tool execution cancelled by user');
		}

		const allOutputs: string[] = [];

		for (let attempt = 0; attempt < maxAttempts; attempt++) {
			// Check for abort signal before each attempt
			if (signal?.aborted) {
				allOutputs.push('⏹️ Poll cancelled by user');
				return this.failure(toolCallId, allOutputs.join('\n\n'));
			}

			// Out of budget: report the attempts we have rather than let the
			// harness timeout reject the whole call with no output at all.
			const remainingMs = deadline - Date.now();
			if (remainingMs <= 0) {
				allOutputs.push(
					`❌ Stopped: poll budget exhausted after ${attempt} attempt(s) — the agent's ` +
					`task budget (${budgetMs}ms) is smaller than the requested poll budget ` +
					`(${pollBudgetMs(args)}ms). Re-run poll to keep waiting.`
				);
				return this.failure(toolCallId, allOutputs.join('\n\n'));
			}

			// Run the check command, never past the deadline
			const output = await this._runCheck(command, cwd, Math.min(commandTimeout, remainingMs));
			const exitCode = output.exitCode;

			allOutputs.push(
				`[Attempt ${attempt + 1}/${maxAttempts}] (exit=${exitCode})\n${output.stdout}`
			);

			// Check success condition
			if (successPattern) {
				try {
					const regex = new RegExp(successPattern);
					if (regex.test(output.stdout)) {
						allOutputs.push(`✅ Success: output matched pattern "${successPattern}"`);
						return this.success(toolCallId, allOutputs.join('\n\n'));
					}
				} catch (err) {
					return this.failure(toolCallId,
						`Invalid regex pattern "${successPattern}": ${(err as Error).message}`
					);
				}
			} else if (exitCode === 0) {
				allOutputs.push(`✅ Success: command exited with code 0`);
				return this.success(toolCallId, allOutputs.join('\n\n'));
			}

			// Not yet succeeded — calculate backoff delay
			if (attempt < maxAttempts - 1) {
				// Check abort before sleeping
				if (signal?.aborted) {
					allOutputs.push('⏹️ Poll cancelled by user');
					return this.failure(toolCallId, allOutputs.join('\n\n'));
				}

				// Exponential backoff: initialDelay * 2^attempt, capped at maxDelay
				const delay = Math.min(initialDelay * Math.pow(2, attempt), maxDelay);
				const delayMs = delay * 1000;

				allOutputs.push(
					`⏳ Waiting ${delay}s before next poll (attempt ${attempt + 2}/${maxAttempts})...`
				);

				// Never sleep past the deadline: wake up and let the top-of-loop
				// check report the budget as exhausted.
				await this._sleep(Math.min(delayMs, Math.max(0, deadline - Date.now())), signal);
			}
		}

		// All attempts exhausted
		allOutputs.push(
			`❌ Failed: condition not met after ${maxAttempts} attempts ` +
			`(total wait ~${this._totalWaitTime(initialDelay, maxDelay, maxAttempts)}s)`
		);
		return this.failure(toolCallId, allOutputs.join('\n\n'));
	}

	private async _runCheck(
		command: string,
		cwd: string,
		timeout: number,
	): Promise<{ stdout: string; exitCode: number | null }> {
		return new Promise<{ stdout: string; exitCode: number | null }>((resolve) => {
			const chunks: string[] = [];
			let settled = false;
			let exitCode: number | null = null;

			const instance = this._terminalService.createTerminal({
				config: {
					name: 'Agent Poll Check',
					cwd,
					isFeatureTerminal: true,
				},
			});

			const cleanup = () => {
				clearTimeout(timer);
				dataDisposable.dispose();
				exitDisposable.dispose();
				instance.dispose();
			};

			const timer = setTimeout(() => {
				if (!settled) {
					settled = true;
					cleanup();
					resolve({
						stdout: chunks.join('').trim(),
						exitCode: exitCode ?? -1,
					});
				}
			}, timeout);

			const dataDisposable = instance.onData(data => {
				chunks.push(data);
			});

			const exitDisposable = instance.onExit(code => {
				if (!settled) {
					settled = true;
					exitCode = code?.code ?? null;
					cleanup();
					clearTimeout(timer);
					resolve({
						stdout: chunks.join('').trim(),
						exitCode: exitCode ?? null,
					});
				}
			});

			instance.sendText(command, true);
		});
	}

	private _sleep(ms: number, signal?: AbortSignal): Promise<void> {
		return new Promise((resolve, reject) => {
			const timer = setTimeout(resolve, ms);
			if (signal) {
				const onAbort = () => {
					clearTimeout(timer);
					reject(new DOMException('Aborted', 'AbortError'));
				};
				if (signal.aborted) {
					clearTimeout(timer);
					reject(new DOMException('Aborted', 'AbortError'));
					return;
				}
				signal.addEventListener('abort', onAbort, { once: true });
			}
		});
	}

	/**
	 * Calculate approximate total wait time for the failure message.
	 */
	private _totalWaitTime(initial: number, max: number, attempts: number): number {
		let total = 0;
		for (let i = 0; i < attempts - 1; i++) {
			total += Math.min(initial * Math.pow(2, i), max);
		}
		return total;
	}
}
